-- cron_run_log: persists one row per scheduled-job invocation so the admin
-- stats endpoint can surface the last TTL-keeper run without polling the
-- underlying cron system.
--
-- Columns:
--   job_name     — machine-readable job identifier (e.g. 'ttl-keeper')
--   run_id       — UUID generated by the job, matches the structured log
--   status       — 'succeeded' | 'partial' | 'failed'
--   summary      — JSONB payload from the job (counts, duration, etc.)
--   completed_at — wall-clock time the run finished (used for ordering)

CREATE TABLE IF NOT EXISTS cron_run_log (
    id           BIGSERIAL    PRIMARY KEY,
    job_name     TEXT         NOT NULL,
    run_id       TEXT         NOT NULL,
    status       TEXT         NOT NULL CHECK (status IN ('succeeded', 'partial', 'failed')),
    summary      JSONB        NOT NULL DEFAULT '{}'::jsonb,
    completed_at TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- The admin stats query orders by completed_at and filters by job_name, so
-- a compound index covers both predicates in one scan.
CREATE INDEX IF NOT EXISTS idx_cron_run_log_job_completed
    ON cron_run_log (job_name, completed_at DESC);
